from slopgate._types import object_dict
def _evaluate_traced_bash(
    tmp_path: Path,
    monkeypatch: MonkeyPatch,
    repo_name: str,
    command: str,
    platform: str,
) -> None:
    repo = write_slopgate(tmp_path / repo_name)
    write_config_from_defaults(tmp_path, monkeypatch, keep_default_config)
    monkeypatch.setenv("SLOPGATE_ROOT", str(tmp_path / "vf-root"))
    _ = evaluate_payload(pretool_bash_payload(repo, command), platform=platform)


def _latest_result_timing(tmp_path: Path) -> dict[str, object]:
    results_path = tmp_path / "vf-root" / "logs" / "results.jsonl"
    records = [
        json.loads(line)
        for line in results_path.read_text(encoding="utf-8").splitlines()
    ]
    return object_dict(records[-1].get("timing"))


